<?php
require $_SERVER['DOCUMENT_ROOT'].'/main.inc.php';
require_once __DIR__.'/../lib/main.lib.php';
require_once DOL_DOCUMENT_ROOT.'/custom/chinaplanetcustomercenter/lib/admin_shell.lib.php';
chinaplanetsp_require_internal($user,'admin');
$action=GETPOST('action','aZ09');
$id=GETPOSTINT('id');

$fields=array('public_label','component_type','container_type','country_code','pod','pol','shipping_line','service_type','incoterm','cargo_type','document_code','calc_type','currency_code','notes_internal');
$readValues=function()use($fields){$out=array();foreach($fields as $field)$out[$field]=trim(GETPOST($field,$field==='notes_internal'?'restricthtml':'alphanohtml'));return $out;};
$quoted=function($value)use($db){return $value!==''?"'".$db->escape($value)."'":'NULL';};

if($action==='save'){
 $label=trim(GETPOST('label','alphanohtml'));$values=$readValues();
 if($label==='')setEventMessages('Internal rule label is required.',null,'errors');
 else{
  $normalized=array('container_type'=>strtoupper($values['container_type']),'country_code'=>strtoupper($values['country_code']),'service_type'=>strtolower($values['service_type']),'incoterm'=>strtoupper($values['incoterm']),'cargo_type'=>strtolower($values['cargo_type']),'document_code'=>strtolower($values['document_code']),'currency_code'=>strtoupper($values['currency_code']?:'USD'));
  foreach($normalized as $key=>$value)$values[$key]=$value;
  $calcType=in_array($values['calc_type'],array('fixed','percent','override'),true)?$values['calc_type']:'fixed';
  $assign="label='".$db->escape($label)."',public_label=".$quoted($values['public_label']).",component_type='".$db->escape($values['component_type']?:'other')."',container_type=".$quoted($values['container_type']).",country_code=".$quoted($values['country_code']).",pod=".$quoted($values['pod']).",pol=".$quoted($values['pol']).",shipping_line=".$quoted($values['shipping_line']).",service_type=".$quoted($values['service_type']).",incoterm=".$quoted($values['incoterm']).",cargo_type=".$quoted($values['cargo_type']).",document_code=".$quoted($values['document_code']).",calc_type='".$db->escape($calcType)."',amount=".price2num(GETPOST('amount','alphanohtml')).",currency_code='".$db->escape($values['currency_code'])."',priority=".GETPOSTINT('priority').",stackable=".(GETPOSTINT('stackable')?1:0).",date_start=".$quoted(GETPOST('date_start','alpha')).",date_end=".$quoted(GETPOST('date_end','alpha')).",notes_internal=".$quoted($values['notes_internal']);
  if($id>0)$sql="UPDATE ".MAIN_DB_PREFIX."chinaplanetsp_rule SET ".$assign.",fk_user_modif=".(int)$user->id." WHERE rowid=".$id." AND entity=".(int)$conf->entity;
  else $sql="INSERT INTO ".MAIN_DB_PREFIX."chinaplanetsp_rule SET entity=".(int)$conf->entity.",".$assign.",status=1,fk_user_creat=".(int)$user->id.",date_creation='".$db->idate(dol_now())."'";
  if($db->query($sql)){setEventMessages($id>0?'Pricing rule updated.':'Pricing rule added.',null,'mesgs');$id=0;}else setEventMessages($db->lasterror(),null,'errors');
 }
}
if($action==='toggle'&&$id>0){$status=GETPOSTINT('status')?1:0;$db->query("UPDATE ".MAIN_DB_PREFIX."chinaplanetsp_rule SET status=".$status.",fk_user_modif=".(int)$user->id." WHERE rowid=".$id." AND entity=".(int)$conf->entity);setEventMessages($status?'Rule enabled.':'Rule disabled.',null,'mesgs');}
if($action==='delete'&&$id>0){if($db->query("DELETE FROM ".MAIN_DB_PREFIX."chinaplanetsp_rule WHERE rowid=".$id." AND entity=".(int)$conf->entity))setEventMessages('Pricing rule deleted.',null,'mesgs');else setEventMessages($db->lasterror(),null,'errors');$id=0;}

$editId=GETPOSTINT('edit');$edit=null;
if($editId>0){$res=$db->query("SELECT * FROM ".MAIN_DB_PREFIX."chinaplanetsp_rule WHERE rowid=".$editId." AND entity=".(int)$conf->entity);$edit=$res?$db->fetch_object($res):null;}
$value=function($name,$default='')use($edit){return dol_escape_htmltag($edit&&isset($edit->$name)?$edit->$name:$default);};
$selected=function($name,$option)use($edit){return $edit&&(string)$edit->$name===(string)$option?' selected':'';};

$css=array(cpcc_admin_shell_asset('/custom/chinaplanetcustomercenter/css/admin_dashboard.css'),cpcc_admin_shell_asset('/custom/chinaplanetshippingprices/css/shippingprices.css'));
llxHeader('','Pricing Rules','','',0,0,array(),$css);cpcc_admin_shell_open('shippingprices','Pricing rules & cases / قواعد وحالات التسعير','EXW والبضائع الخطرة والبطاريات والمستندات ورسوم الوجهة','fa-layer-group');
print '<main class="chinaplanetsp-rules-admin"><div class="chinaplanetsp-admin-toolbar"><a class="button" href="dashboard.php">Control center</a><a class="button" href="../index.php">Price inquiry</a></div>';
print '<div class="info">Each rule adds a fixed amount or percentage when all filled conditions match. Empty conditions mean “any”. Customer label is visible in the price breakdown; internal notes never appear to external users.</div>';
print '<section class="chinaplanetsp-rule-editor"><h2>'.($edit?'Edit case / تعديل الحالة':'Add case / إضافة حالة').'</h2><form method="post"><input type="hidden" name="token" value="'.newToken().'"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="'.($edit?(int)$edit->rowid:0).'"><div class="chinaplanetsp-rule-grid">';
print '<label><span>Internal name *</span><input name="label" required value="'.$value('label').'" placeholder="Battery handling Egypt"></label><label><span>Customer label</span><input name="public_label" value="'.$value('public_label').'" placeholder="Dangerous goods surcharge"></label>';
print '<label><span>Component</span><select name="component_type">';foreach(array('destination'=>'Destination / POD','origin'=>'EXW / inland','cargo'=>'Cargo / dangerous goods','document'=>'Document','other'=>'Other')as$k=>$v)print '<option value="'.$k.'"'.$selected('component_type',$k).'>'.$v.'</option>';print '</select></label>';
print '<label><span>Calculation</span><div class="chinaplanetsp-inline"><select name="calc_type"><option value="fixed"'.$selected('calc_type','fixed').'>Fixed</option><option value="percent"'.$selected('calc_type','percent').'>Percent</option><option value="override"'.$selected('calc_type','override').'>Set exact price</option></select><input name="amount" value="'.$value('amount','0').'" inputmode="decimal"><input name="currency_code" value="'.$value('currency_code','USD').'" maxlength="3"></div></label>';
print '<label><span>Container</span><input name="container_type" value="'.$value('container_type').'" placeholder="20GP / 40HQ"></label><label><span>Country code</span><input name="country_code" value="'.$value('country_code').'" maxlength="2" placeholder="EG"></label><label><span>POD</span><input name="pod" value="'.$value('pod').'" placeholder="SOKHNA"></label><label><span>POL</span><input name="pol" value="'.$value('pol').'" placeholder="Shenzhen"></label><label><span>Shipping line</span><input name="shipping_line" value="'.$value('shipping_line').'" placeholder="PIL"></label>';
print '<label><span>Service</span><select name="service_type"><option value="">Any</option><option value="direct"'.$selected('service_type','direct').'>Direct</option><option value="transit"'.$selected('service_type','transit').'>Transit</option></select></label><label><span>Incoterm</span><select name="incoterm"><option value="">Any</option><option value="FOB"'.$selected('incoterm','FOB').'>FOB</option><option value="EXW"'.$selected('incoterm','EXW').'>EXW</option></select></label>';
print '<label><span>Cargo case</span><select name="cargo_type"><option value="">Any</option>';foreach(array('normal'=>'Normal','battery'=>'Battery','oil'=>'Oil / liquid','powder'=>'Powder','chemical'=>'Chemical','copy_brand'=>'Copy brand')as$k=>$v)print '<option value="'.$k.'"'.$selected('cargo_type',$k).'>'.$v.'</option>';print '</select></label><label><span>Document code</span><input name="document_code" value="'.$value('document_code').'" placeholder="cargox / saber"></label>';
print '<label><span>Valid from</span><input type="date" name="date_start" value="'.$value('date_start').'"></label><label><span>Valid until</span><input type="date" name="date_end" value="'.$value('date_end').'"></label><label><span>Priority</span><input name="priority" value="'.$value('priority','100').'" inputmode="numeric"></label><label class="chinaplanetsp-rule-check"><input type="checkbox" name="stackable" value="1"'.(!$edit||(int)$edit->stackable?' checked':'').'><span>Add with other matching rules</span></label><label class="chinaplanetsp-rule-note"><span>Internal note</span><textarea name="notes_internal" rows="3" placeholder="Staff-only explanation">'.$value('notes_internal').'</textarea></label>';
print '</div><div class="chinaplanetsp-rule-actions"><button class="button button-save" type="submit">'.($edit?'Save changes / حفظ التعديل':'Add rule / إضافة القاعدة').'</button>'.($edit?'<a class="button" href="rules.php">Cancel</a>':'').'</div></form></section>';
print '<section class="chinaplanetsp-rule-list"><h2>Saved rules / القواعد المحفوظة</h2><div class="div-table-responsive"><table class="noborder centpercent"><tr class="liste_titre"><th>Rule</th><th>Scope</th><th>Price</th><th>Status</th><th>Actions</th></tr>';
$res=$db->query("SELECT * FROM ".MAIN_DB_PREFIX."chinaplanetsp_rule WHERE entity=".(int)$conf->entity." ORDER BY status DESC,priority DESC,rowid DESC");if($res)while($rule=$db->fetch_object($res)){$scope=array_filter(array($rule->container_type,$rule->country_code,$rule->pod,$rule->pol,$rule->shipping_line,$rule->service_type,$rule->incoterm,$rule->cargo_type,$rule->document_code));print '<tr><td><strong>'.dol_escape_htmltag($rule->label).'</strong><small>'.dol_escape_htmltag($rule->public_label).'</small></td><td>'.dol_escape_htmltag(implode(' · ',$scope)?:'Any matching inquiry').'</td><td>'.price($rule->amount).' '.dol_escape_htmltag($rule->calc_type==='percent'?'%':$rule->currency_code).'</td><td>'.((int)$rule->status?'Enabled':'Disabled').'</td><td class="chinaplanetsp-row-actions"><a class="button smallpaddingimp" href="?edit='.(int)$rule->rowid.'">Edit</a><form method="post"><input type="hidden" name="token" value="'.newToken().'"><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="'.(int)$rule->rowid.'"><input type="hidden" name="status" value="'.((int)$rule->status?0:1).'"><button class="button smallpaddingimp">'.((int)$rule->status?'Disable':'Enable').'</button></form><form method="post" onsubmit="return confirm(\'Delete this pricing rule permanently?\')"><input type="hidden" name="token" value="'.newToken().'"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="'.(int)$rule->rowid.'"><button class="button button-delete smallpaddingimp">Delete</button></form></td></tr>';}
print '</table></div></section></main>';cpcc_admin_shell_close();llxFooter();$db->close();
